window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-f1801ef8ed07533a"]={"versions": [{"id": "FIG-f1801ef8ed07533a", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Definition einer Datenstruktur im Kontext der AUTOSAR E2E-Bibliothek (End-to-End Communication Protection Library), spezifisch für das E2E-Profil 5. Es spezifiziert den internen Zustandsdatentyp für die senderseitige E2E-Schutzfunktion (<code>Protect</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert eine einzelne Datenstruktur (<code>«structure»</code>):</p>\n<ul class=\"fig-list\">\n<li>Typname: <code>E2E_P05ProtectStateType</code> innerhalb des Namensraums/Pakets <code>E2E_P05Types</code></li>\n<li>Attribute:</li>\n<li><code>+ Counter :uint8</code>: Öffentliches Datenfeld zur Verwaltung des fortlaufenden Sendezählers (Sequenzzähler) mit dem elementaren Datentyp <code>uint8</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturdiagramm ohne dynamische Ablauf- oder Verhaltensmodellierung. Der Zustandstyp speichert den Ausführungszustand zwischen aufeinanderfolgenden Aufrufen der Schutzfunktion <code>E2E_P05Protect</code>, wobei der Sequenzzähler inkrementiert wird.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Datenstruktur-Spezifikation für die E2E-Bibliothek gemäß AUTOSAR. Die Struktur <code>E2E_P05ProtectStateType</code> ist vom Aufrufer vorzuhalten und als Ein-/Ausgangsparameter an die Schutzfunktion zu übergeben; das Attribut <code>Counter</code> muss im Wertebereich von <code>uint8</code> gemäß Profil-5-Spezifikation zyklisch hochgezählt werden.</p>"}, {"id": "FIG-77621bf21d279752", "releases": ["R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Definition einer Datenstruktur im Kontext der AUTOSAR E2E-Bibliothek (End-to-End Communication Protection Library), spezifisch für das E2E-Profil 5. Es spezifiziert den internen Zustandsdatentyp für die senderseitige E2E-Schutzfunktion (<code>Protect</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert eine einzelne Datenstruktur (<code>«structure»</code>):</p>\n<ul class=\"fig-list\">\n<li>Typname: <code>E2E_P05ProtectStateType</code> innerhalb des hierarchischen Namensraums/Pakets <code>E2E::E2E_P05Types</code></li>\n<li>Attribute:</li>\n<li><code>+ Counter :uint8</code>: Öffentliches Datenfeld zur Verwaltung des fortlaufenden Sendezählers (Sequenzzähler) mit dem elementaren Datentyp <code>uint8</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturdiagramm ohne dynamische Ablauf- oder Verhaltensmodellierung. Der Zustandstyp speichert den Ausführungszustand zwischen aufeinanderfolgenden Aufrufen der Schutzfunktion <code>E2E_P05Protect</code>, wobei der Sequenzzähler inkrementiert wird.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Datenstruktur-Spezifikation für die E2E-Bibliothek gemäß AUTOSAR. Die Struktur <code>E2E_P05ProtectStateType</code> ist vom Aufrufer vorzuhalten und als Ein-/Ausgangsparameter an die Schutzfunktion zu übergeben; das Attribut <code>Counter</code> muss im Wertebereich von <code>uint8</code> gemäß Profil-5-Spezifikation zyklisch hochgezählt werden.</p>"}, {"id": "FIG-7db3fbc43df45aa0", "releases": ["R18-10_R4.4.0_R1.5.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Definition einer Datenstruktur im Kontext der AUTOSAR E2E-Bibliothek (End-to-End Communication Protection Library), spezifisch für das E2E-Profil 5. Es spezifiziert den internen Zustandsdatentyp für die senderseitige E2E-Schutzfunktion (<code>Protect</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert eine einzelne Datenstruktur (<code>«structure»</code>):</p>\n<ul class=\"fig-list\">\n<li>Typname: <code>E2E_P05ProtectStateType</code> innerhalb des Namensraums/Pakets <code>E2E_P05Types</code></li>\n<li>Attribute:</li>\n<li><code>+ Counter: uint8</code>: Öffentliches Datenfeld zur Verwaltung des fortlaufenden Sendezählers (Sequenzzähler) mit dem elementaren Datentyp <code>uint8</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturdiagramm ohne dynamische Ablauf- oder Verhaltensmodellierung. Der Zustandstyp speichert den Ausführungszustand zwischen aufeinanderfolgenden Aufrufen der Schutzfunktion <code>E2E_P05Protect</code>, wobei der Sequenzzähler inkrementiert wird.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Datenstruktur-Spezifikation für die E2E-Bibliothek gemäß AUTOSAR. Die Struktur <code>E2E_P05ProtectStateType</code> ist vom Aufrufer vorzuhalten und als Ein-/Ausgangsparameter an die Schutzfunktion zu übergeben; das Attribut <code>Counter</code> muss im Wertebereich von <code>uint8</code> gemäß Profil-5-Spezifikation zyklisch hochgezählt werden.</p>"}, {"id": "FIG-59e02ea349792489", "releases": ["R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Definition einer Datenstruktur im Kontext der AUTOSAR E2E-Bibliothek (End-to-End Communication Protection Library), spezifisch für das E2E-Profil 5. Es spezifiziert den internen Zustandsdatentyp für die senderseitige E2E-Schutzfunktion (<code>Protect</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert eine einzelne Datenstruktur (<code>«structure»</code>):</p>\n<ul class=\"fig-list\">\n<li>Typname: <code>E2E_P05ProtectStateType</code> innerhalb des Namensraums/Pakets <code>E2E_P05Types</code></li>\n<li>Attribute:</li>\n<li><code>+ Counter: uint8</code>: Öffentliches Datenfeld zur Verwaltung des fortlaufenden Sendezählers (Sequenzzähler) mit dem elementaren Datentyp <code>uint8</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturdiagramm ohne dynamische Ablauf- oder Verhaltensmodellierung. Der Zustandstyp speichert den Ausführungszustand zwischen aufeinanderfolgenden Aufrufen der Schutzfunktion <code>E2E_P05Protect</code>, wobei der Sequenzzähler inkrementiert wird.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Datenstruktur-Spezifikation für die E2E-Bibliothek gemäß AUTOSAR. Die Struktur <code>E2E_P05ProtectStateType</code> ist vom Aufrufer vorzuhalten und als Ein-/Ausgangsparameter an die Schutzfunktion zu übergeben; das Attribut <code>Counter</code> muss im Wertebereich von <code>uint8</code> gemäß Profil-5-Spezifikation zyklisch hochgezählt werden.</p>"}], "trans": [{"from": "FIG-f1801ef8ed07533a", "to": "FIG-77621bf21d279752", "fr": "R4.2.2", "tr": "R4.3.1", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li>Stereotyp/Klassenbezeichner: Paketpfad um den übergeordneten Namensraum <code>E2E</code> zu <code>E2E::E2E_P05Types::E2E_P05ProtectStateType</code> erweitert.</li>\n</ul>"}, {"from": "FIG-77621bf21d279752", "to": "FIG-7db3fbc43df45aa0", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li>Stereotyp/Klassenbezeichner: Paketpfad wieder auf <code>E2E_P05Types::E2E_P05ProtectStateType</code> gekürzt (Präfix <code>E2E::</code> entfernt).</li>\n<li>Attributbereich: Leerzeichen vor dem Doppelpunkt bei <code>Counter: uint8</code> entfernt.</li>\n</ul>"}, {"from": "FIG-7db3fbc43df45aa0", "to": "FIG-59e02ea349792489", "fr": "R18-10_R4.4.0_R1.5.0", "tr": "R19-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
